#include <stdio.h>
#include <stdlib.h>
#include <ctype.h>
#include <errno.h>

#define MAX_INPUT 1000000
#define ITERATIONS 60

static int is_valid_number(const char *s) {
    while (isspace((unsigned char)*s)) s++;
    if (*s == '+' || *s == '-') s++;
    if (!isdigit((unsigned char)*s)) return 0;
    while (isdigit((unsigned char)*s)) s++;
    while (isspace((unsigned char)*s)) s++;
    return *s == '\0';
}

static double bisection_sqrt(long N) {
    double low = 0.0;
    double high = (double)N + 1.0; // constant 1.0 as in original binary
    double mid;
    for (int i = 0; i < ITERATIONS; ++i) {
        mid = low + (high - low) * 0.5;
        if ((double)N < mid * mid) {
            high = mid;
        } else {
            low = mid;
        }
    }
    return mid;
}

int main(int argc, char *argv[]) {
    if (argc < 2) {
        puts("NO_INPUT");
        return 0;
    }
    char *endptr = NULL;
    errno = 0;
    long value = strtol(argv[1], &endptr, 10);
    if (endptr == argv[1] || *endptr != '\0' || errno == ERANGE) {
        puts("BAD_INPUT");
        return 0;
    }
    if (value < 0) {
        puts("BAD_INPUT");
        return 0;
    }
    if (value > MAX_INPUT) {
        puts("OUT_OF_RANGE");
        return 0;
    }
    double result = bisection_sqrt(value);
    printf("%.6f\n", result);
    return 0;
}
